svg.script:
const benchmarks = {
  all: "All benchmarks",
  "pt-exams": "PT Exams",
  "alba-mcq": "ALBA-MCQ",
  "cultura-viva": "Cultura Viva",
  "legalbench-pt": "LegalBench PT",
};
const datasetRepositories = {
  "pt-exams": "amalia-llm/pt_exams",
  "alba-mcq": "amalia-llm/alba_mcq",
  "cultura-viva": "amalia-llm/cultura-viva-pt-mcq",
  "legalbench-pt": "BeatrizCanaverde/LegalBench.PT",
};
const modelRepositories = {
  "qwen3.5-2b": "Qwen/Qwen3.5-2B",
  "qwen3.5-4b": "Qwen/Qwen3.5-4B",
  "qwen3.5-4b-no-think": "Qwen/Qwen3.5-4B",
  "lfm2.5-2.6b": "LiquidAI/LFM2.5-2.6B",
  "smollm3-3b": "HuggingFaceTB/SmolLM3-3B",
  "smollm3-3b-no-think": "HuggingFaceTB/SmolLM3-3B",
  "nemotron-3-nano-4b": "nvidia/NVIDIA-Nemotron-3-Nano-4B-BF16",
  "amalia-9b-sft": "amalia-llm/AMALIA-9B-0626-SFT",
  "amalia-9b-dpo": "amalia-llm/AMALIA-9B-0626-DPO",
};
const datasetDescriptions = {
  "pt-exams": "Portuguese exam questions across school subjects.",
  "alba-mcq": "Portuguese linguistics, from phonetics and grammar to wordplay.",
  "cultura-viva": "Multiple-choice questions about Portuguese culture.",
  "legalbench-pt": "Portuguese legal questions across 30 fields of law.",
};
const palette = {
  Alibaba: "#0875df",
  "Liquid AI": "#3348c7",
  "Hugging Face": "#292929",
  NVIDIA: "#278443",
  AMALIA: "#b96149",
};
const models = {
  "qwen3.5-2b": ["Qwen3.5", "2B (think)", palette.Alibaba, "Alibaba"],
  "qwen3.5-4b": ["Qwen3.5", "4B (think)", palette.Alibaba, "Alibaba"],
  "qwen3.5-4b-no-think": ["Qwen3.5", "4B", palette.Alibaba, "Alibaba"],
  "lfm2.5-2.6b": ["LFM2.5", "2.6B (think)", palette["Liquid AI"], "Liquid AI"],
  "smollm3-3b": [
    "SmolLM3",
    "3B (think)",
    palette["Hugging Face"],
    "Hugging Face",
  ],
  "smollm3-3b-no-think": [
    "SmolLM3",
    "3B",
    palette["Hugging Face"],
    "Hugging Face",
  ],
  "nemotron-3-nano-4b": [
    "Nemotron 3 Nano",
    "4B (think)",
    palette.NVIDIA,
    "NVIDIA",
  ],
  "amalia-9b-sft": ["AMALIA SFT", "9B", palette.AMALIA, "AMALIA"],
  "amalia-9b-dpo": ["AMALIA DPO", "9B", palette.AMALIA, "AMALIA"],
};
function logoId({ family }) {
  return `logo-${family.toLowerCase().replaceAll(" ", "-")}`;
}
function escapeXML({ value }) {
  return String(value).replace(
    /[<>&"']/g,
    (character) =>
      ({
        "<": "&lt;",
        ">": "&gt;",
        "&": "&amp;",
        '"': "&quot;",
        "'": "&apos;",
      })[character],
  );
}
function summarize({ data, benchmark }) {
  return Object.keys(models).map((model) => {
    const rows = data.filter(
      (row) =>
        row.model === model && (benchmark === "all" || row.task === benchmark),
    );
    if (rows.length !== (benchmark === "all" ? 4 : 1))
      throw new Error(`Incomplete results for ${model}`);
    return {
      model,
      score:
        rows.reduce((sum, row) => sum + row.accuracy * 100, 0) / rows.length,
      tokens: rows.reduce((sum, row) => sum + row.output_tokens, 0),
      errors: rows.reduce((sum, row) => sum + row.sample_errors, 0),
      samples: rows.reduce((sum, row) => sum + row.samples, 0),
      size: rows[0].parameters_b,
    };
  });
}
function frontier({ rows, axis }) {
  return rows
    .filter(
      (row) =>
        !rows.some(
          (other) =>
            other[axis] <= row[axis] &&
            other.score >= row.score &&
            (other[axis] < row[axis] || other.score > row.score),
        ),
    )
    .sort((a, b) => a[axis] - b[axis]);
}
function compact({ value }) {
  if (value >= 1e6)
    return `${(value / 1e6).toFixed(2).replace(/0$/, "").replace(/\.0$/, "")}M`;
  if (value >= 1e3) return `${(value / 1e3).toFixed(1).replace(/\.0$/, "")}k`;
  return String(value);
}
function chartMarkup({ data, kind, state }) {
  const { benchmark, axis, menu = null } = state;
  const rows = summarize({ data, benchmark });
  const scatter = kind === "frontier",
    tokens = kind === "tokens";
  const heading = scatter
    ? `Intelligence vs. ${axis === "tokens" ? "output tokens" : "model size"}`
    : tokens
      ? "Output tokens"
      : "Portuguese benchmark intelligence";
  const text = ({
    x,
    y,
    value,
    size = 12,
    fill = "#252525",
    anchor = "start",
    extra = "",
  }) =>
    `<text x="${x}" y="${y}" font-size="${size}" fill="${fill}" text-anchor="${anchor}" ${extra}>${escapeXML({ value })}</text>`;
  const modelLabel = ({
    row,
    x,
    y,
    size = 11,
    anchor = "start",
    extra = "",
  }) => {
    const [name, variant] = models[row.model];
    const thinking = variant.includes("(think)");
    const title = `${name} ${variant.replace(" (think)", "")}`;
    return `<text class="model-label" x="${x}" y="${y}" font-size="${size}" fill="#252525" text-anchor="${anchor}" ${extra}><tspan x="${x}" y="${y}">${escapeXML({ value: title })}</tspan>${thinking ? `<tspan class="thinking-label" x="${x}" dy="14">(think)</tspan>` : ""}</text>`;
  };
  const modelLogo = ({ row, x, y, size = 20 }) =>
    `<use class="model-logo" href="#${logoId({ family: models[row.model][3] })}" x="${x}" y="${y}" width="${size}" height="${size}" aria-hidden="true"/>`;
  const line = ({ x1, y1, x2, y2, extra = "" }) =>
    `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="#d4d4d4" ${extra}/>`;
  const dropdown = ({ field, label, choices, y }) => {
    const x = 450,
      width = 222;
    const open = menu === field;
    const trigger = `<g class="control" role="combobox" tabindex="0" aria-label="${label}" aria-haspopup="listbox" aria-expanded="${open}" aria-controls="${field}-options" data-dropdown="${field}"><rect x="${x}" y="${y}" width="${width}" height="34" rx="4" fill="#f2f3f4" stroke="#dedfe1"/>${text({ x: x + 13, y: y + 22, value: choices[state[field]], size: 13 })}${text({ x: x + width - 15, y: y + 21, value: "⌄", anchor: "middle", size: 16 })}</g>`;
    const options = Object.entries(choices)
      .map(([value, title], index) => {
        const optionY = y + 38 + index * 34;
        return `<g class="option" role="option" tabindex="-1" aria-selected="${state[field] === value}" data-field="${field}" data-value="${value}"><rect x="${x + 1}" y="${optionY}" width="${width - 2}" height="34" fill="${state[field] === value ? "#edf2fa" : "#fff"}"/>${text({ x: x + 13, y: optionY + 22, value: title, size: 13 })}</g>`;
      })
      .join("");
    const popup = `<g id="${field}-options" role="listbox" aria-label="${label}" data-popup="${field}" visibility="${open ? "visible" : "hidden"}"><rect x="${x}" y="${y + 37}" width="${width}" height="${Object.keys(choices).length * 34 + 2}" rx="4" fill="white" stroke="#bfc3c9"/>${options}</g>`;
    return { trigger, popup };
  };
  const controls = [
    dropdown({
      field: "benchmark",
      label: "Benchmark",
      choices: Object.fromEntries(
        Object.entries(benchmarks).map(([value, title]) => {
          const samples = summarize({ data, benchmark: value })[0].samples;
          return [value, `${title} (N=${samples.toLocaleString("en-US")})`];
        }),
      ),
      y: 22,
    }),
  ];
  if (scatter)
    controls.push(
      dropdown({
        field: "axis",
        label: "Horizontal axis",
        choices: { size: "Parameters · B", tokens: "Output tokens" },
        y: 66,
      }),
    );
  let markup = `<rect width="700" height="520" fill="white"/><title>${escapeXML({ value: heading })}</title><desc>Select a benchmark in the top-right dropdown. Focus or tap a model for exact values. Models marked (think) use thinking. Unmarked models do not.</desc>`;
  markup += text({
    x: 28,
    y: 39,
    value: heading,
    size: 23,
    extra: 'style="font-family:Georgia,serif"',
  });
  markup += text({
    x: 28,
    y: 63,
    value: tokens
      ? "Recorded output tokens · Lower is better"
      : benchmark === "all"
        ? `Average of ${Object.keys(benchmarks).length - 1} benchmark accuracies · ${rows[0].samples.toLocaleString("en-US")} questions`
        : `Accuracy on ${rows[0].samples.toLocaleString("en-US")} questions · Higher is better`,
    fill: "#666",
    size: 12,
    extra: 'id="chart-subtitle"',
  });
  const left = 64,
    right = 672,
    top = 132,
    bottom = scatter ? 410 : 340;
  const plotWidth = right - left,
    plotHeight = bottom - top;
  if (scatter) {
    // Midpoints in display space: geometric on the log x-axis, arithmetic on y.
    markup += `<g id="quadrant-shading" pointer-events="none"><rect id="attractive-quadrant" x="${left}" y="${top}" width="${plotWidth / 2}" height="${plotHeight / 2}" fill="#e3fae3"/><rect x="${left + plotWidth / 2}" y="${top + plotHeight / 2}" width="${plotWidth / 2}" height="${plotHeight / 2}" fill="#fafafa"/></g>`;
    markup += `<rect x="${left}" y="96" width="10" height="10" rx="1" fill="#e3fae3" stroke="#a6e9ad"/>`;
    markup += text({
      x: left + 17,
      y: 105,
      value: "Most attractive quadrant",
      size: 11,
    });
    markup += line({
      x1: left + 177,
      x2: left + 200,
      y1: 101,
      y2: 101,
      extra: 'style="stroke:#404040" stroke-width="1.6" stroke-dasharray="2 5"',
    });
    markup += text({
      x: left + 209,
      y: 105,
      value: "Pareto frontier",
      size: 11,
    });
  }
  const sorted = [...rows].sort((a, b) =>
    tokens ? a.tokens - b.tokens : b.score - a.score,
  );
  const biggest = Math.max(...rows.map((row) => row.tokens));
  const magnitude = 10 ** Math.floor(Math.log10(biggest));
  const maximum = tokens ? Math.ceil(biggest / magnitude) * magnitude : 100;
  const minimum = scatter ? 30 : 0,
    intervals = scatter ? 7 : 5;
  const y = (value) =>
    bottom - ((value - minimum) / (maximum - minimum)) * plotHeight;
  markup += text({
    x: left,
    y: 119,
    value: tokens ? "Output tokens" : "Accuracy, %",
    fill: "#666",
    size: 11,
  });
  if (scatter)
    markup += text({
      x: right,
      y: 119,
      value: "Ring = Pareto optimal",
      anchor: "end",
      fill: "#666",
      size: 11,
    });
  for (let index = 0; index <= intervals; index++) {
    const value = minimum + ((maximum - minimum) * index) / intervals;
    markup += line({
      x1: left,
      x2: right,
      y1: y(value),
      y2: y(value),
      extra: 'stroke-dasharray="2 5"',
    });
    markup += text({
      x: left - 12,
      y: y(value) + 4,
      value: tokens ? compact({ value }) : value,
      anchor: "end",
      fill: "#666",
      size: 11,
    });
  }
  const detail = (row) => [
    `${models[row.model][0]} ${models[row.model][1]}`,
    `${row.score.toFixed(2)}% ${benchmark === "all" ? "mean accuracy" : "accuracy"} · ${row.size}B parameters`,
    `${row.tokens.toLocaleString("en-US")} output tokens`,
    `${row.samples.toLocaleString("en-US")} questions · ${row.errors} errors counted incorrect`,
  ];
  const mark = ({ row, content }) =>
    `<g class="mark" tabindex="0" role="button" aria-label="${escapeXML({ value: detail(row).join(". ") })}" data-model="${row.model}" data-detail="${escapeXML({ value: JSON.stringify(detail(row)) })}">${content}</g>`;
  if (!scatter) {
    const step = plotWidth / rows.length,
      barWidth = 38;
    sorted.forEach((row, index) => {
      const center = left + step * (index + 0.5);
      const value = tokens ? row.tokens : row.score;
      const barHeight = bottom - y(value);
      const [name, variant, color] = models[row.model];
      // Do not inflate tiny token bars just to fit text. Their values remain in details.
      const valueLabel =
        barHeight >= 18
          ? text({
              x: center,
              y: y(value) + barHeight / 2 + 4,
              value: tokens ? compact({ value }) : row.score.toFixed(1),
              anchor: "middle",
              size: 10.5,
              fill: "#fff",
              extra: 'class="bar-value" font-weight="600"',
            })
          : "";
      const logo = modelLogo({ row, x: center - 10, y: bottom + 8 });
      const labelY = bottom + 44;
      const label = modelLabel({
        row,
        x: center + 4,
        y: labelY,
        anchor: "end",
        size: 12,
        extra: `transform="rotate(-45 ${center + 4} ${labelY})"`,
      });
      markup += mark({
        row,
        content: `<rect class="bar" x="${center - barWidth / 2}" y="${y(value)}" width="${barWidth}" height="${barHeight}" rx="2.5" fill="${color}"/><rect x="${center - 28}" y="${Math.min(y(value), bottom - 20)}" width="56" height="${Math.max(20, barHeight)}" fill="transparent"/>${valueLabel}${logo}${label}`,
      });
    });
  } else {
    const minimumX = Math.min(...rows.map((row) => row[axis])) / 1.4;
    const maximumX = Math.max(...rows.map((row) => row[axis])) * 1.85;
    const x = (value) =>
      left +
      (Math.log(value / minimumX) / Math.log(maximumX / minimumX)) * plotWidth;
    const optimal = frontier({ rows, axis });
    const ticks =
      axis === "size"
        ? [2, 2.6, 3, 4, 6, 9]
        : [
            1e3, 2e3, 5e3, 1e4, 2e4, 5e4, 1e5, 2e5, 5e5, 1e6, 2e6, 5e6, 1e7,
            2e7, 5e7,
          ];
    ticks
      .filter((value) => value >= minimumX && value <= maximumX)
      .forEach((value) => {
        markup += line({
          x1: x(value),
          x2: x(value),
          y1: top,
          y2: bottom,
          extra: 'stroke-dasharray="2 5" opacity="0.65"',
        });
        markup += text({
          x: x(value),
          y: bottom + 23,
          value: axis === "size" ? value : compact({ value }),
          anchor: "middle",
          fill: "#666",
          size: 11,
        });
      });
    // Steps represent observed models within a budget, not interpolated performance.
    let path = `M ${x(optimal[0][axis])} ${y(optimal[0].score)}`;
    optimal.slice(1).forEach((row) => {
      path += ` H ${x(row[axis])} V ${y(row.score)}`;
    });
    markup += `<path d="${path} H ${right}" fill="none" stroke="#404040" stroke-width="1.6" stroke-dasharray="2 5"/>`;
    const occupied = [];
    const positions = rows.map((row) => ({
      row,
      px: x(row[axis]),
      py: y(row.score),
    }));
    for (const { row, px, py } of positions.sort((a, b) => a.py - b.py)) {
      const [name, variant, color] = models[row.model];
      const label = `${name} ${variant.replace(" (think)", "")}`;
      const width = label.length * 5.8 + 22,
        height = variant.includes("(think)") ? 28 : 20;
      const candidates = [-14, 26, -42, 54, -70, 82, -98, 110].flatMap((dy) => [
        [13, dy],
        [-width - 13, dy],
      ]);
      const boxes = candidates.map(([dx, dy]) => ({
        x: Math.max(left + 3, Math.min(right - width, px + dx)),
        y: Math.max(top + 14, Math.min(bottom - height, py + dy)),
        width,
        height,
      }));
      const collision = (box) =>
        occupied.some(
          (other) =>
            box.x < other.x + other.width + 6 &&
            box.x + width + 6 > other.x &&
            box.y - 14 < other.y + other.height - 8 &&
            box.y + height - 8 > other.y - 14,
        ) ||
        positions.some(
          (point) =>
            point.px > box.x - 8 &&
            point.px < box.x + width + 8 &&
            point.py > box.y - 17 &&
            point.py < box.y + height - 4,
        );
      const box = boxes.find((box) => !collision(box)) || boxes[0];
      occupied.push(box);
      const leader = line({
        x1: px,
        y1: py,
        x2: box.x > px ? box.x - 3 : box.x + width + 3,
        y2: box.y - 4,
        extra: 'stroke-width="0.8" style="stroke:#999"',
      });
      const logo = modelLogo({ row, x: box.x, y: box.y - 11, size: 17 });
      const labelMarkup = modelLabel({
        row,
        x: box.x + 22,
        y: box.y,
        extra:
          'paint-order="stroke" stroke="white" stroke-width="3" stroke-linejoin="round"',
      });
      markup += mark({
        row,
        content: `${leader}${logo}${labelMarkup}${optimal.includes(row) ? `<circle cx="${px}" cy="${py}" r="8.5" fill="white" stroke="#333" stroke-width="1.2"/>` : ""}<circle class="model-point" cx="${px}" cy="${py}" r="5.5" fill="${color}" stroke="white" stroke-width="1"/><circle cx="${px}" cy="${py}" r="12" fill="transparent"/>`,
      });
    }
    markup += text({
      x: (left + right) / 2,
      y: bottom + 53,
      value:
        axis === "size"
          ? "Nominal model size · billions of parameters · log scale"
          : "Recorded output tokens · log scale",
      anchor: "middle",
      size: 12,
    });
  }
  const datasetLink = ({ task, x }) =>
    `<a class="dataset-link" href="https://huggingface.co/datasets/${datasetRepositories[task]}" target="_blank" rel="noopener noreferrer" aria-label="${benchmarks[task]} on Hugging Face">${text({ x, y: 500, value: benchmarks[task], size: 11, fill: "#555" })}</a>`;
  if (benchmark !== "all") {
    markup += datasetLink({ task: benchmark, x: 28 });
    const descriptionX = 28 + benchmarks[benchmark].length * 6.2 + 26;
    markup += text({
      x: descriptionX - 13,
      y: 500,
      value: "·",
      size: 11,
      fill: "#999",
    });
    markup += text({
      x: descriptionX,
      y: 500,
      value: datasetDescriptions[benchmark],
      size: 11,
      fill: "#777",
      extra: 'id="dataset-description"',
    });
  }
  markup +=
    '<g id="tooltip" role="group" aria-label="Model details" visibility="hidden" pointer-events="auto" aria-live="polite"/>';
  markup +=
    controls.map((control) => control.trigger).join("") +
    controls.map((control) => control.popup).join("");
  return markup;
}
function bindChart({ data, kind, initialState }) {
  const root = document.documentElement,
    canvas = document.getElementById("canvas");
  const state = { ...initialState, menu: null };
  let tooltipOwner = null,
    hideTimer = null,
    pinned = false;
  const hideTooltip = () => {
    clearTimeout(hideTimer);
    const tooltip = document.getElementById("tooltip");
    if (tooltip.contains(document.activeElement) && tooltipOwner?.isConnected)
      tooltipOwner.focus();
    tooltip.setAttribute("visibility", "hidden");
    pinned = false;
  };
  const render = ({ focus = null } = {}) => {
    clearTimeout(hideTimer);
    pinned = false;
    tooltipOwner = null;
    canvas.innerHTML = chartMarkup({ data, kind, state });
    root.dataset.benchmark = state.benchmark;
    root.dataset.axis = state.axis;
    if (focus) canvas.querySelector(focus)?.focus();
  };
  const closeMenu = ({ focus = false } = {}) => {
    if (!state.menu) return;
    const field = state.menu;
    state.menu = null;
    canvas
      .querySelector(`[data-popup="${field}"]`)
      .setAttribute("visibility", "hidden");
    const trigger = canvas.querySelector(`[data-dropdown="${field}"]`);
    trigger.setAttribute("aria-expanded", "false");
    if (focus) trigger.focus();
  };
  const showTooltip = ({ target }) => {
    closeMenu();
    clearTimeout(hideTimer);
    const tooltip = document.getElementById("tooltip");
    if (
      tooltipOwner === target &&
      tooltip.getAttribute("visibility") === "visible"
    )
      return;
    tooltipOwner = target;
    pinned = false;
    const model = target.dataset.model;
    const row = summarize({ data, benchmark: state.benchmark }).find(
      (row) => row.model === model,
    );
    const [name, variant, , family] = models[model];
    const title = `${name} ${variant.replace(" (think)", "")}`;
    const url = `https://huggingface.co/${modelRepositories[model]}`;
    tooltip.innerHTML = `<rect x="380" y="110" width="292" height="164" rx="6" fill="white" stroke="#dce0e5" style="filter:drop-shadow(0 3px 7px #00000018)"/>
      <use href="#${logoId({ family })}" x="394" y="124" width="24" height="24" aria-hidden="true"/>
      <text x="430" y="134" font-size="13" font-weight="600" fill="#252525">${escapeXML({ value: title })}</text>
      ${variant.includes("(think)") ? '<text x="430" y="151" font-size="10" fill="#777">Thinking enabled</text>' : ""}
      <line x1="394" y1="162" x2="658" y2="162" stroke="#ededed"/>
      <text x="394" y="181" font-size="10" fill="#777">${state.benchmark === "all" ? "Mean accuracy" : "Accuracy"}</text>
      <text x="526" y="181" font-size="10" fill="#777">Output tokens</text>
      <text data-metric="score" x="394" y="204" font-size="20" font-weight="600" fill="#252525">${row.score.toFixed(2)}%</text>
      <text data-metric="tokens" x="526" y="203" font-size="15" font-weight="600" fill="#252525">${row.tokens.toLocaleString("en-US")}</text>
      <text x="394" y="224" font-size="10" fill="#777">${row.samples.toLocaleString("en-US")} questions · ${row.errors} errors</text>
      <line x1="394" y1="237" x2="658" y2="237" stroke="#ededed"/>
      <a id="model-link" tabindex="-1" href="${url}" target="_blank" rel="noopener noreferrer" aria-label="Open ${escapeXML({ value: title })} on Hugging Face"><rect x="388" y="240" width="276" height="29" rx="3" fill="white"/><text x="394" y="259" font-size="11" fill="#2468a0">View model on Hugging Face</text><text x="656" y="259" text-anchor="end" font-size="13" fill="#2468a0">↗</text></a>`;
    tooltip.setAttribute("visibility", "visible");
  };
  const activate = ({ target }) => {
    if (target.dataset.dropdown) {
      const field = target.dataset.dropdown;
      state.menu = state.menu === field ? null : field;
      render({ focus: `[data-dropdown="${field}"]` });
    } else if (target.dataset.field) {
      const { field, value } = target.dataset;
      state[field] = value;
      state.menu = null;
      render({ focus: `[data-dropdown="${field}"]` });
    } else if (target.dataset.detail) {
      showTooltip({ target });
      pinned = true;
    }
  };
  canvas.addEventListener("click", (event) => {
    if (event.target.closest("a")) return;
    const target = event.target.closest(".control, .option, .mark");
    if (target) activate({ target });
    else {
      hideTooltip();
      closeMenu();
    }
  });
  canvas.addEventListener("keydown", (event) => {
    const target = event.target.closest(".control, .option, .mark");
    if (event.key === "Escape") {
      hideTooltip();
      closeMenu({ focus: true });
      return;
    }
    if (
      event.key === "Tab" &&
      event.shiftKey &&
      event.target.closest("#model-link")
    ) {
      event.preventDefault();
      tooltipOwner?.focus();
      return;
    }
    if (!target) return;
    if (["Enter", " "].includes(event.key)) {
      event.preventDefault();
      activate({ target });
      return;
    }
    if (event.key === "Tab") {
      if (
        !event.shiftKey &&
        target.classList.contains("mark") &&
        document.getElementById("tooltip").getAttribute("visibility") ===
          "visible"
      ) {
        event.preventDefault();
        document.getElementById("model-link").focus();
        return;
      }
      closeMenu({ focus: true });
      return;
    }
    const field = target.dataset.dropdown || target.dataset.field;
    if (!field || !["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key))
      return;
    event.preventDefault();
    const wasOpen = state.menu === field;
    state.menu = field;
    const choices =
      field === "benchmark" ? Object.keys(benchmarks) : ["size", "tokens"];
    let index = choices.indexOf(target.dataset.value || state[field]);
    if (event.key === "Home") index = 0;
    else if (event.key === "End") index = choices.length - 1;
    else if (wasOpen)
      index =
        (index + (event.key === "ArrowDown" ? 1 : -1) + choices.length) %
        choices.length;
    render({
      focus: `[data-field="${field}"][data-value="${choices[index]}"]`,
    });
  });
  for (const type of ["pointerover", "focusin"])
    canvas.addEventListener(type, (event) => {
      if (event.target.closest("#tooltip")) clearTimeout(hideTimer);
      const target = event.target.closest(".mark");
      if (target) showTooltip({ target });
    });
  for (const type of ["pointerout", "focusout"])
    canvas.addEventListener(type, (event) => {
      if (!event.target.closest(".mark, #tooltip") || pinned) return;
      const next = event.relatedTarget;
      if (
        next?.closest?.("#tooltip") ||
        next?.closest?.(".mark") === tooltipOwner
      )
        return;
      clearTimeout(hideTimer);
      hideTimer = setTimeout(() => {
        const tooltip = document.getElementById("tooltip");
        if (
          !tooltip.matches(":hover") &&
          !tooltip.contains(document.activeElement)
        )
          hideTooltip();
      }, 220);
    });
  root.dataset.ready = "true";
}

